CREATE DATABASE IF NOT EXISTS reskill CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE reskill;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS gallery_comments,gallery_likes,gallery_photos,quiz_results,questions,quizzes,learning_progress,recycling_gallery,videos,educational_materials,tutorials,waste_categories,users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE waste_categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE educational_materials(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,title VARCHAR(200) NOT NULL,summary TEXT,content LONGTEXT NOT NULL,material_type ENUM('article','tutorial') NOT NULL DEFAULT 'article',duration INT DEFAULT 5,level VARCHAR(30) DEFAULT 'Dasar',references_text TEXT,status ENUM('draft','published') NOT NULL DEFAULT 'published',created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES waste_categories(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE tutorials(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,title VARCHAR(200) NOT NULL,description TEXT,materials TEXT,steps LONGTEXT,status ENUM('draft','published') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES waste_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE videos(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,title VARCHAR(200) NOT NULL,description TEXT,video_url VARCHAR(500) NOT NULL,source_name VARCHAR(200),duration INT DEFAULT 0,status ENUM('draft','published') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES waste_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE quizzes(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,description TEXT,level VARCHAR(30) DEFAULT 'Dasar',status ENUM('draft','published') NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE questions(id INT AUTO_INCREMENT PRIMARY KEY,quiz_id INT NOT NULL,question TEXT NOT NULL,option_a VARCHAR(255) NOT NULL,option_b VARCHAR(255) NOT NULL,option_c VARCHAR(255) NOT NULL,option_d VARCHAR(255) NOT NULL,correct_option ENUM('A','B','C','D') NOT NULL,explanation TEXT,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE quiz_results(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,quiz_id INT NOT NULL,score DECIMAL(5,2) NOT NULL DEFAULT 0,correct_count INT DEFAULT 0,total_questions INT DEFAULT 0,answers_json LONGTEXT,completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE learning_progress(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,material_id INT NOT NULL,is_completed TINYINT(1) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY unique_user_material(user_id,material_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(material_id) REFERENCES educational_materials(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE recycling_gallery(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NULL,title VARCHAR(200) NOT NULL,description TEXT,materials TEXT,steps LONGTEXT,photo VARCHAR(255) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES waste_categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE gallery_photos(id INT AUTO_INCREMENT PRIMARY KEY,gallery_id INT NOT NULL,photo VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(gallery_id) REFERENCES recycling_gallery(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE gallery_likes(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,gallery_id INT NOT NULL,UNIQUE KEY uniq_like(user_id,gallery_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(gallery_id) REFERENCES recycling_gallery(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE gallery_comments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,gallery_id INT NOT NULL,comment TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(gallery_id) REFERENCES recycling_gallery(id) ON DELETE CASCADE) ENGINE=InnoDB;
