INSERT INTO waste_categories(name,description) VALUES
('Organik','Limbah yang mudah terurai secara alami, seperti sisa makanan, kulit buah, dan daun.'),
('Anorganik','Limbah yang sulit terurai, seperti plastik, kaca, kertas tertentu, dan logam.'),
('B3','Limbah bahan berbahaya dan beracun yang memerlukan penanganan khusus.'),
('Residu','Sisa sampah yang belum dapat dimanfaatkan kembali melalui proses pemilahan dan daur ulang umum.');
INSERT INTO educational_materials(category_id,title,summary,content,material_type,duration,level,references_text,status) VALUES
(1,'Mengenal Limbah Organik','Memahami pengertian, ciri, contoh, dan pengelolaan limbah organik.','## Pengertian\nLimbah organik adalah sisa bahan yang berasal dari makhluk hidup dan umumnya dapat terurai secara biologis. Contohnya sisa sayuran, kulit buah, daun kering, dan ampas kopi.\n\n## Ciri-ciri\nLimbah organik umumnya mudah membusuk, dapat diuraikan mikroorganisme, dan bila dikelola dengan tepat dapat menjadi sumber bahan organik bagi tanah.\n\n## Cara pengelolaan\nPisahkan dari sampah lain. Sisa makanan tertentu dapat diolah melalui pengomposan atau budidaya maggot sesuai jenis dan kondisi bahan. Daun kering dapat dicacah sebagai bahan kompos.\n\n## Hal yang perlu diperhatikan\nHindari memasukkan bahan berbahaya, plastik, atau bahan yang tidak sesuai ke dalam komposter. Jaga keseimbangan bahan basah dan kering serta sirkulasi udara.\n\n## Rangkuman\nPemilahan sejak sumber memudahkan pengolahan limbah organik menjadi kompos dan mengurangi sampah yang dibuang.','article',6,'Dasar','Kementerian Lingkungan Hidup dan Kehutanan. Informasi pengelolaan sampah. https://sipsn.menlhk.go.id/\nUnited Nations Environment Programme. (2021). Food Waste Index Report 2021. https://www.unep.org/resources/report/unep-food-waste-index-report-2021','published'),
(2,'Mengenal Limbah Anorganik','Kenali contoh limbah anorganik dan cara memilahnya untuk didaur ulang.','## Pengertian\nLimbah anorganik adalah kelompok limbah yang banyak berasal dari bahan nonhayati atau bahan olahan yang membutuhkan waktu lama untuk terurai. Contohnya botol plastik, kaleng, kaca, dan beberapa jenis kemasan.\n\n## Pemilahan\nPisahkan berdasarkan jenis material. Kosongkan dan bersihkan kemasan jika memungkinkan, lalu keringkan sebelum disimpan. Periksa simbol atau kode material pada kemasan.\n\n## Pemanfaatan\nMaterial yang masih layak dapat digunakan kembali atau disalurkan ke bank sampah dan fasilitas daur ulang. Tidak semua jenis plastik dapat diproses oleh setiap fasilitas, sehingga ikuti ketentuan penerima setempat.\n\n## Rangkuman\nPemilahan yang benar membantu menjaga kualitas material dan meningkatkan peluang pemanfaatan kembali.','article',7,'Dasar','Kementerian Lingkungan Hidup dan Kehutanan. Sistem Informasi Pengelolaan Sampah Nasional. https://sipsn.menlhk.go.id/\nUNEP. (2023). Turning off the Tap: How the world can end plastic pollution and create a circular economy. https://www.unep.org/resources/turning-off-tap-end-plastic-pollution-create-circular-economy','published'),
(3,'Mengenal Limbah B3 Rumah Tangga','Memahami contoh limbah berbahaya dan cara penanganan awal yang aman.','## Pengertian\nLimbah B3 adalah limbah yang karena sifat, konsentrasi, atau jumlahnya dapat membahayakan kesehatan dan lingkungan. Di rumah tangga, contohnya baterai bekas, lampu tertentu, kemasan bahan kimia, dan obat kedaluwarsa.\n\n## Prinsip penanganan\nJangan mencampurkan limbah B3 dengan sampah biasa. Simpan sementara dalam wadah tertutup, tidak mudah bocor, dan beri penanda. Jauhkan dari anak-anak, sumber panas, dan makanan.\n\n## Penyaluran\nSerahkan melalui fasilitas pengumpulan atau pengelola yang memiliki kewenangan. Jangan membakar, membongkar, atau menuangkan bahan kimia ke saluran air.\n\n## Rangkuman\nKenali simbol bahaya, pisahkan, simpan dengan aman, dan gunakan jalur pengumpulan yang sesuai.','article',8,'Dasar','Republik Indonesia. Peraturan Pemerintah Nomor 22 Tahun 2021 tentang Penyelenggaraan Perlindungan dan Pengelolaan Lingkungan Hidup. https://peraturan.bpk.go.id/\nKementerian Lingkungan Hidup dan Kehutanan. Informasi pengelolaan limbah B3. https://www.menlhk.go.id/','published'),
(4,'Mengenal Sampah Residu','Memahami sampah residu dan cara mengurangi jumlahnya.','## Pengertian\nSampah residu adalah sisa yang tidak dapat dimanfaatkan kembali melalui pemilahan dan fasilitas daur ulang yang tersedia. Contohnya dapat berbeda bergantung pada sistem pengelolaan setempat.\n\n## Cara mengurangi\nKurangi produk sekali pakai, pilih barang yang tahan lama, gunakan kembali barang yang masih layak, dan pilah material yang dapat didaur ulang sebelum menentukan residu.\n\n## Penanganan\nBuang residu sesuai layanan pengangkutan dan ketentuan daerah. Jangan memasukkan limbah B3 ke tempat sampah residu biasa.\n\n## Rangkuman\nResidu sebaiknya menjadi pilihan terakhir setelah upaya pengurangan, penggunaan kembali, dan pemilahan dilakukan.','article',5,'Dasar','Republik Indonesia. Undang-Undang Nomor 18 Tahun 2008 tentang Pengelolaan Sampah. https://peraturan.bpk.go.id/\nKementerian Lingkungan Hidup dan Kehutanan. SIPSN. https://sipsn.menlhk.go.id/','published'),
(NULL,'Memahami Prinsip 3R','Pelajari Reduce, Reuse, dan Recycle dalam kehidupan sehari-hari.','## Reduce\nReduce berarti mengurangi timbulan sampah sejak awal. Contohnya membawa botol minum dan tas belanja pakai ulang, memilih produk dengan kemasan lebih sedikit, serta merencanakan pembelian.\n\n## Reuse\nReuse berarti menggunakan kembali barang yang masih layak. Contohnya memakai stoples sebagai wadah penyimpanan atau menggunakan kertas pada sisi yang masih kosong.\n\n## Recycle\nRecycle berarti mendaur ulang material menjadi bahan atau produk baru melalui proses yang sesuai. Contohnya kertas dan logam yang dipilah untuk didaur ulang.\n\n## Urutan prioritas\nMengurangi dan menggunakan kembali umumnya lebih diutamakan daripada mendaur ulang karena dapat mencegah timbulan sampah sejak awal.\n\n## Rangkuman\nTerapkan 3R secara konsisten mulai dari rumah, sekolah, dan lingkungan sekitar.','article',7,'Dasar','Republik Indonesia. Undang-Undang Nomor 18 Tahun 2008 tentang Pengelolaan Sampah. https://peraturan.bpk.go.id/\nUnited Nations Environment Programme. (2024). Global Waste Management Outlook 2024. https://www.unep.org/resources/global-waste-management-outlook-2024','published'),
(1,'Panduan Membuat Kompos Sederhana','Langkah praktik mengolah sisa organik rumah tangga menjadi kompos.','## Tujuan\nMengolah sisa organik yang sesuai menjadi kompos untuk membantu memperbaiki kualitas tanah.\n\n## Bahan dan alat\nSisa sayur dan buah yang tidak berminyak, daun kering, tanah atau kompos matang sebagai starter, wadah berlubang, dan alat pengaduk.\n\n## Langkah pembuatan\n1. Pilah sisa organik dan buang bagian yang tidak sesuai.\n2. Cacah bahan menjadi ukuran lebih kecil.\n3. Masukkan bahan basah dan bahan kering secara berlapis.\n4. Jaga kondisi lembap seperti spons diperas, bukan becek.\n5. Aduk secara berkala agar udara masuk.\n6. Tunggu hingga bahan berubah menjadi remah gelap dan berbau tanah.\n\n## Tips\nJika terlalu basah, tambahkan daun kering. Jika terlalu kering, tambahkan sedikit air. Hindari daging, tulang, minyak, dan produk susu pada komposter sederhana tertutup karena dapat mengundang hama.','tutorial',10,'Menengah','United States Environmental Protection Agency. Composting at Home. https://www.epa.gov/recycle/composting-home\nKementerian Lingkungan Hidup dan Kehutanan. SIPSN. https://sipsn.menlhk.go.id/','published');
