INSERT INTO questions(quiz_id,question,option_a,option_b,option_c,option_d,correct_option,explanation) VALUES
(1,'Manakah contoh limbah organik?','Botol kaca','Kulit pisang','Baterai bekas','Kaleng minuman','B','Kulit pisang berasal dari bahan hayati dan dapat terurai secara biologis.'),
(1,'Baterai bekas rumah tangga sebaiknya diperlakukan sebagai apa?','Sampah organik','Sampah residu biasa','Limbah yang perlu penanganan khusus','Bahan kompos','C','Baterai bekas dapat mengandung bahan berbahaya sehingga perlu jalur pengumpulan khusus.'),
(1,'Apa langkah awal yang tepat sebelum mendaur ulang botol plastik?','Mencampur dengan sisa makanan','Memilah dan mengosongkan botol','Membakar botol','Mengubur botol','B','Pemilahan dan pembersihan membantu menjaga kualitas material.'),
(1,'Apa yang dimaksud sampah residu?','Sampah yang selalu bisa dikomposkan','Sisa yang belum dapat dimanfaatkan melalui proses umum','Semua jenis sampah organik','Bahan baku baru','B','Residu merupakan sisa setelah upaya pemilahan dan pemanfaatan yang tersedia.'),
(1,'Mengapa limbah B3 tidak boleh dicampur dengan sampah biasa?','Agar lebih berat','Dapat menimbulkan risiko bagi kesehatan dan lingkungan','Supaya cepat membusuk','Agar mudah dijual','B','Limbah B3 memerlukan penanganan khusus untuk mengurangi risiko.'),
(2,'Apa arti Reduce?','Mengurangi timbulan sampah','Membakar sampah','Membuang sampah ke sungai','Mencampur semua sampah','A','Reduce berarti mengurangi sampah sejak awal.'),
(2,'Contoh tindakan Reuse adalah...','Membeli kantong sekali pakai','Menggunakan kembali stoples sebagai wadah','Membakar kertas','Membuang botol ke sungai','B','Reuse berarti memakai kembali barang yang masih layak.'),
(2,'Recycle berarti...','Mengurangi pembelian','Menggunakan barang satu kali','Mendaur ulang material menjadi bahan atau produk baru','Menyimpan sampah tanpa memilah','C','Recycle adalah proses daur ulang material.'),
(2,'Mengapa Reduce perlu diprioritaskan?','Mencegah sampah sejak sumbernya','Menambah jumlah kemasan','Membuat sampah tercampur','Menghilangkan kebutuhan memilah','A','Mengurangi konsumsi dapat mencegah timbulan sampah sejak awal.'),
(2,'Membawa tas belanja pakai ulang termasuk contoh...','Reduce','Residu','Limbah B3','Pembuangan akhir','A','Tas pakai ulang mengurangi kebutuhan kantong sekali pakai.');
